import logging

from taf.internal.managedobject import ManagedObject
from taf.converters.base import ConverterComponent
from taf.internal.execution.base import ExecutionError

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TwDecoderConverter(ManagedObject, ConverterComponent):
    def __init__(
            self,
            input_file_path,
            executor,
            tti_trace_decoder_options="parquet",
            tti_dec_bin_path="/opt/tti-dec/tti-dec-bin",
            tti_dec_venv_path="/opt/tti-dec/venv",
            stdout_path=None,
            stderr_path=None,
            **kwargs,
    ):
        super(TwDecoderConverter, self).__init__(**kwargs)
        self._input_file_path = input_file_path
        self._executor = executor
        self._tti_dec_bin_path = tti_dec_bin_path
        self._tti_dec_venv_path = tti_dec_venv_path
        self._tti_trace_decoder_options = tti_trace_decoder_options
        self._stdout_path = stdout_path
        self._stderr_path = stderr_path

    def convert(self):
        """
        Robot Keyword to convert the input TTI Trace .pcap file to parquet format.

        """

        command = (
            f"source '{self._tti_dec_venv_path}/bin/activate' ; "
            f"python3 \"$(find '{self._tti_dec_bin_path}' -name TtiTraceDecoder.py)\" {self._input_file_path} "
            f"{self._tti_trace_decoder_options}"
        )

        stdout, stderr, exit_status = self._executor.raw_execute(command)

        if exit_status:
            raise ExecutionError(
                stdout=stdout,
                stderr=stderr,
                exit_status=exit_status,
            )

        if self._stdout_path:
            self._write_output(stdout, self._stdout_path)
            logger.info(f"Twdecoder stdout written to {self._stdout_path!r}")

        if self._stderr_path:
            self._write_output(stderr, self._stderr_path)
            logger.info(f"Twdecoder stderr written to {self._stderr_path!r}")


    def _write_output(self, output, path):
            with open(path, 'wb') as file:
                file.write(output)
